        # factor p-1 to check divisors
        r = None
        # brute force compute order by checking divisors of p-1
        dlist = divisors(p-1)
        dlist.sort()
        for d in dlist:
            if pow(3, d, p) == 1:
                r = d
                break
        if r is None:
            continue
        # We need r even
        if r % 2 != 0:
            continue
        s = r // 2
        if p * s <= LIMIT:
            final_primes.append(p)
            ord_cache[p] = r
    final_primes = sorted(set(final_primes))
    # Build combinations of powers of these primes
    # To keep combinations manageable, we will DFS over distinct primes building n,
    # and at each node we check the necessary condition that for every prime q dividing current n,
    # pow(3, n, q) == q-1 (i.e., 3^n ≡ -1 mod q). However, we will do final checking on n itself.
    primes_no2 = [p for p in final_primes if p != 2]
    # Precompute possible powers for each prime
    powers_opts = {}
    for p in final_primes:
        opts = [1]
        pe = p
        while pe <= LIMIT:
            opts.append(pe)
            pe *= p
        powers_opts[p] = opts

    found = set()
    # DFS over primes (including 2) to assemble n
    plist = final_primes
    Npr = len(plist)
    sys.setrecursionlimit(10000)
    def dfs(idx, cur):
        # At each node test cur as candidate n (cur >=1)
        if cur <= LIMIT:
            # verify condition n | 3^n + 1
            # compute 3^cur mod cur
            if pow(3, cur, cur) == (cur - 1) % cur:
                found.add(cur)
        if idx == Npr:
            return
        p = plist[idx]
        for pe in powers_opts[p]:
            if pe == 1:
                # skip multiplying by 1 but continue to next prime
                dfs(idx+1, cur)
            else:
                if cur * pe > LIMIT:
                    break
                dfs(idx+1, cur * pe)
    dfs(0, 1)
    # Convert found to sorted list and sum
    s = sum(found)
    print(s)

if __name__ == "__main__":
    main()
