                break
        if skip_to_next_n:
            continue
        return False
    return True

# --- Pollard's Rho for factoring ---
def pollards_rho(n):
    if n % 2 == 0:
        return 2
    if n % 3 == 0:
        return 3
    # random polynomial f(x) = x^2 + c
    while True:
        x = random.randrange(2, n-1)
        y = x
        c = random.randrange(1, n-1)
        d = 1
        while d == 1:
            x = (x*x + c) % n
            y = (y*y + c) % n
            y = (y*y + c) % n
            d = math.gcd(abs(x - y), n)
            if d == n:
                break
        if d > 1 and d < n:
            return d

def factor(n, res):
    if n == 1:
        return
    if is_probable_prime(n):
        res.append(n)
    else:
        d = pollards_rho(n)
        factor(d, res)
        factor(n//d, res)

