    if n % 3 == 0:
        continue
    # skip multiples of 4
    if n & 3 == 0:
        continue
    if pow(3, n, n) == (n - 1) % n:
        results.add(n)

# Finally sum results <= LIMIT
ans = sum(x for x in results if x <= LIMIT)
print(ans)

